5. // Imports
6. //==================================================================================================
7. 
8. use vstd::prelude::*;
9. #[cfg(verus_keep_ghost)]
10. include!("region.spec.rs");
11. #[cfg(verus_keep_ghost)]
12. include!("region.proof.rs");
13. 
14. use crate::hal::mem::types::{
15.     access::AccessPermission,
16.     address::{
17.         Address,
18.         PageAligned,
19.         PhysicalAddress,
20.         VirtualAddress,
21.     },
22. };
23. use ::alloc::string::{
24.     String,
25.     ToString,
26. };
27. use ::arch::mem::PAGE_ALIGNMENT;
28. use ::sys::error::{
29.     Error,
30.     ErrorCode,
31. };
32. 
33. //==================================================================================================
34. // Memory Region Type
35. //==================================================================================================
36. 
37. ///
38. /// # Description
39. ///
40. /// A type that represents the type of a memory region.
41. ///
42. #[derive(Debug, Clone, Copy, Eq, PartialEq)]
43. #[verus_verify]
44. pub enum MemoryRegionType {
45.     /// Usable memory.
46.     Usable,
47.     /// Reserved memory.
48.     Reserved,
49.     /// Memory mapped I/O.
50.     Mmio,
51.     /// Bad memory.
52.     Bad,
53. }
54. 
55. //==================================================================================================
56. // MMIO Cache Policy
57. //==================================================================================================
58. 
59. ///
60. /// # Description
61. ///
62. /// Caching policy for MMIO memory regions. Controls the PWT (Page Write-Through) and PCD
63. /// (Page Cache Disable) bits in the page table entries that back the region.
64. ///
65. #[verus_verify(external_derive)]
66. #[derive(Debug, Clone, Copy, Eq, PartialEq)]
67. pub struct MmioCachePolicy {
68.     /// If `true`, the page is mapped with the Write-Through attribute (PWT=1).
69.     write_through: bool,
70.     /// If `true`, caching is enabled for the page (PCD=0).
71.     cache_enabled: bool,
72. }
73. 
74. impl MmioCachePolicy {
75.     ///
76.     /// # Description
77.     ///
78.     /// Creates a new MMIO cache policy.
79.     ///
80.     /// # Parameters
81.     ///
82.     /// - `write_through`: If `true`, enables the Write-Through attribute (PWT=1).
83.     /// - `cache_enabled`: If `true`, enables caching for the page (PCD=0).
84.     ///
85.     /// # Returns
86.     ///
87.     /// A new [`MmioCachePolicy`] instance.
88.     ///
89.     pub const fn new(write_through: bool, cache_enabled: bool) -> Self {
90.         Self {
91.             write_through,
92.             cache_enabled,
93.         }
94.     }
95. 
96.     /// Uncacheable: Write-Through Enabled, Cache Disabled.
97.     pub const UNCACHEABLE: Self = Self {
98.         write_through: true,
99.         cache_enabled: false,
100.     };
101. 
102.     /// Write-Back: Write-Through Disabled, Cache Enabled.
103.     pub const WRITE_BACK: Self = Self {
104.         write_through: false,
105.         cache_enabled: true,
106.     };
107. 
108.     ///
109.     /// # Description
110.     ///
111.     /// Returns whether the Write-Through attribute is set.
112.     ///
113.     /// # Returns
114.     ///
115.     /// `true` if the page is mapped with the Write-Through attribute (PWT=1).
116.     ///
117.     pub fn write_through(&self) -> bool {
118.         self.write_through
119.     }
120. 
121.     ///
122.     /// # Description
123.     ///
124.     /// Returns whether caching is enabled.
125.     ///
126.     /// # Returns
127.     ///
128.     /// `true` if caching is enabled for the page (PCD=0).
129.     ///
130.     pub fn cache_enabled(&self) -> bool {
131.         self.cache_enabled
132.     }
133. }
134. //==================================================================================================
135. // Memory Region
136. //==================================================================================================
137. 
138. ///
139. /// # Description
140. ///
141. /// A memory region.
142. ///
143. #[verus_verify(external_derive)]
144. #[derive(Debug, Clone)]
145. pub struct MemoryRegion<T: Address> {
146.     name: String,
147.     start: T,
148.     size: usize,
149.     typ: MemoryRegionType,
150.     perm: AccessPermission,
151.     cache_policy: Option<MmioCachePolicy>,
152. }
153. 
154. impl<T: Address> MemoryRegion<T> {
155.     /// Maximum byte-length of a memory region name.
156.     const MEMORY_REGION_NAME_MAX: usize = 32;
157. 
158.     /// Creates a new memory region.
159.     pub fn new(
160.         name: &str,
161.         start: T,
162.         size: usize,
163.         typ: MemoryRegionType,
164.         perm: AccessPermission,
165.     ) -> Result<Self, Error> {
166.         // Check if name is too long (byte length).
167.         if name.len() > Self::MEMORY_REGION_NAME_MAX {
168.             let reason: &str = "memory region name is too long";
169.             error!("{reason} (name.len={}, NAME_MAX={})", name.len(), Self::MEMORY_REGION_NAME_MAX);
170.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
171.         }
172. 
173.         // Check if size of the memory region is valid.
174.         if size == 0 {
175.             return Err(Error::new(ErrorCode::InvalidArgument, "invalid memory region size"));
176.         }
177. 
178.         // Check if memory region is too big.
179.         let start_raw_addr: usize = start.clone().into_raw_value();
180.         let end_raw_addr: usize = match start_raw_addr.checked_add(size - 1) {
181.             Some(end_raw_addr) => end_raw_addr,
182.             None => {
183.                 return Err(Error::new(ErrorCode::TooBig, "memory region is too big"));
184.             },
185.         };
186. 
187.         // Check if memory region spans outside the address space.
188.         if end_raw_addr > T::max_addr() {
189.             return Err(Error::new(
190.                 ErrorCode::InvalidArgument,
191.                 "memory region spans outside the address space",
192.             ));
193.         }
194. 
195.         Ok(Self {
196.             name: name.to_string(),
197.             start,
198.             size,
199.             typ,
200.             perm,
201.             cache_policy: None,
202.         })
203.     }
204. 
205.     pub fn name(&self) -> String {
206.         self.name.clone()
207.     }
208. 
209.     /// Returns the first valid address that lies in the target memory region.
210.     #[verus_spec(result =>
211.         ensures
212.             result@ == self@.start,
213.     )]
214.     pub fn start(&self) -> T {
215.         // The postcondition `result@ == self@.start` relies on `T::clone`
216.         // preserving the abstract address (`clone(x)@ == x@`). `Clone` is a
217.         // supertrait of `Address` with no spec yet, and `assume_specification`
218.         // cannot target a generic trait method. This obligation is therefore
219.         // discharged once the address layer exposes a clone contract; deferred
220.         // here (proving phase).
221.         proof! { admit(); }
222.         self.start.clone()
223.     }
224. 
225.     /// Returns the size of the target memory region.
226.     #[verus_spec(result =>
227.         ensures
228.             result as int == self@.size,
229.     )]
230.     pub fn size(&self) -> usize {
231.         self.size
232.     }
233. 
234.     /// Returns the type of the target memory region.
235.     pub fn typ(&self) -> MemoryRegionType {
236.         self.typ
237.     }
238. 
239.     /// Returns the permissions of the target memory region.
240.     pub fn perm(&self) -> AccessPermission {
241.         self.perm
242.     }
243. 
244.     ///
245.     /// # Description
246.     ///
247.     /// Returns the MMIO cache policy of the target memory region, if set.
248.     ///
249.     /// # Returns
250.     ///
251.     /// The [`MmioCachePolicy`] if one was assigned, or `None` otherwise.
252.     ///
253.     pub fn cache_policy(&self) -> Option<MmioCachePolicy> {
254.         self.cache_policy
255.     }
256. 
257.     ///
258.     /// # Description
259.     ///
260.     /// Sets the MMIO cache policy of the target memory region.
261.     ///
262.     /// # Parameters
263.     ///
264.     /// - `policy`: The cache policy to assign.
265.     ///
266.     pub fn set_cache_policy(&mut self, policy: MmioCachePolicy) {
267.         self.cache_policy = Some(policy);
268.     }
269. }
270. 
271. impl<T: Address> PartialEq for MemoryRegion<T> {
272.     fn eq(&self, other: &Self) -> bool {
273.         self.name == other.name
274.             && self.start == other.start
275.             && self.size == other.size
276.             && self.typ == other.typ
277.             && self.perm == other.perm
278.             && self.cache_policy == other.cache_policy
279.     }
280. }
281. 
282. impl<T: Address> Eq for MemoryRegion<T> {}
283. 
284. impl<T: Address> PartialOrd for MemoryRegion<T> {
285.     fn partial_cmp(&self, other: &Self) -> Option<core::cmp::Ordering> {
286.         Some(self.cmp(other))
287.     }
288. }
289. 
290. impl<T: Address> Ord for MemoryRegion<T> {
291.     fn cmp(&self, other: &Self) -> core::cmp::Ordering {
292.         self.start.cmp(&other.start)
293.     }
294. }
295. 
296. //==================================================================================================
297. // Truncated Memory Region
298. //==================================================================================================
299. 
300. ///
301. /// # Description
302. ///
303. /// A memory region that has been truncated to a multiple of a page size.
304. ///
305. #[verus_verify(external_derive)]
306. #[derive(Clone)]
307. pub struct TruncatedMemoryRegion<T: Address>(MemoryRegion<PageAligned<T>>);
308. 
309. impl<T: Address> TruncatedMemoryRegion<T> {
310.     /// Creates a new truncated memory region.
311.     pub fn new(
312.         name: &str,
313.         start: PageAligned<T>,
314.         size: usize,
315.         typ: MemoryRegionType,
316.         perm: AccessPermission,
317.     ) -> Result<Self, Error> {
318.         // Truncate the size of the memory region to a multiple of the page size.
319.         let size: usize = ::sys::mm::align_up(size, PAGE_ALIGNMENT).ok_or_else(|| {
320.             let reason: &str = "align_up overflow";
321.             error!("TruncatedMemoryRegion::new(): {reason} (name={name:?}, size={size})");
322.             Error::new(ErrorCode::InvalidArgument, reason)
323.         })?;
324.         Ok(Self(MemoryRegion::new(name, start, size, typ, perm)?))
325.     }
326. 
327.     ///
328.     /// # Description
329.     ///
330.     /// Creates a new truncated MMIO memory region with an explicit cache policy.
331.     ///
332.     /// # Parameters
333.     ///
334.     /// - `name`: Name of the memory region.
335.     /// - `start`: Page-aligned start address.
336.     /// - `size`: Size of the region in bytes (rounded up to page alignment).
337.     /// - `perm`: Access permissions for the region.
338.     /// - `cache_policy`: Caching policy that controls PWT/PCD bits in page table entries.
339.     ///
340.     /// # Returns
341.     ///
342.     /// Upon successful completion, a new [`TruncatedMemoryRegion`] with type
343.     /// [`MemoryRegionType::Mmio`] is returned. Upon failure, an error is returned instead.
344.     ///
345.     pub fn new_mmio(
346.         name: &str,
347.         start: PageAligned<T>,
348.         size: usize,
349.         perm: AccessPermission,
350.         cache_policy: MmioCachePolicy,
351.     ) -> Result<Self, Error> {
352.         let mut region: Self = Self::new(name, start, size, MemoryRegionType::Mmio, perm)?;
353.         region.0.set_cache_policy(cache_policy);
354.         Ok(region)
355.     }
356. 
357.     pub fn from_memory_region(region: MemoryRegion<T>) -> Result<Self, Error> {
358.         let cache_policy: Option<MmioCachePolicy> = region.cache_policy();
359.         let start: T = region.start().align_down(PAGE_ALIGNMENT)?;
360.         let start: PageAligned<T> = PageAligned::from_address(start)?;
361.         let name: String = region.name();
362.         let size: usize = region.size();
363.         let typ: MemoryRegionType = region.typ();
364.         let perm: AccessPermission = region.perm();
365.         let mut truncated: Self = Self::new(&name, start, size, typ, perm)?;
366.         if let Some(policy) = cache_policy {
367.             truncated.0.set_cache_policy(policy);
368.         }
369.         Ok(truncated)
370.     }
371. 
372.     pub fn name(&self) -> String {
373.         self.0.name()
374.     }
375. 
376.     /// Returns the first valid address that lies in the target memory region.
377.     #[verus_spec(result =>
378.         ensures
379.             result@ == self@.start,
380.     )]
381.     pub fn start(&self) -> PageAligned<T> {
382.         self.0.start()
383.     }
384. 
385.     /// Returns the size of the target memory region.
386.     #[verus_spec(result =>
387.         ensures
388.             result as int == self@.size,
389.     )]
390.     pub fn size(&self) -> usize {
391.         self.0.size()
392.     }
393. 
394.     /// Returns the type of the target memory region.
395.     pub fn typ(&self) -> MemoryRegionType {
396.         self.0.typ()
397.     }
398. 
399.     /// Returns the permissions of the target memory region.
400.     pub fn perm(&self) -> AccessPermission {
401.         self.0.perm()
402.     }
403. 
404.     ///
405.     /// # Description
406.     ///
407.     /// Returns the MMIO cache policy of the target memory region, if set.
408.     ///
409.     /// # Returns
410.     ///
411.     /// The [`MmioCachePolicy`] if one was assigned, or `None` otherwise.
412.     ///
413.     pub fn cache_policy(&self) -> Option<MmioCachePolicy> {
414.         self.0.cache_policy()
415.     }
416. }
417. 
418. impl<T: Address> PartialEq for TruncatedMemoryRegion<T> {
419.     fn eq(&self, other: &Self) -> bool {
420.         self.0 == other.0
421.     }
422. }
423. 
424. impl<T: Address> Eq for TruncatedMemoryRegion<T> {}
425. 
426. impl<T: Address> PartialOrd for TruncatedMemoryRegion<T> {
427.     fn partial_cmp(&self, other: &Self) -> Option<core::cmp::Ordering> {
428.         Some(self.cmp(other))
429.     }
430. }
431. 
432. impl<T: Address> Ord for TruncatedMemoryRegion<T> {
433.     fn cmp(&self, other: &Self) -> core::cmp::Ordering {
434.         self.0.cmp(&other.0)
435.     }
436. }
437. 
438. impl<T: Address> core::fmt::Debug for TruncatedMemoryRegion<T> {
439.     fn fmt(&self, f: &mut core::fmt::Formatter) -> core::fmt::Result {
440.         write!(
441.             f,
442.             "TruncatedMemoryRegion {{ name: {}, start: {:?}, size: {}, typ: {:?}, perm: {:?}, \
443.              cache_policy: {:?} }}",
444.             self.name(),
445.             self.start(),
446.             self.size(),
447.             self.typ(),
448.             self.perm(),
449.             self.cache_policy()
450.         )
451.     }
452. }
453. 
454. //==================================================================================================
455. // Standalone Functions
456. //==================================================================================================
457. 
458. impl TruncatedMemoryRegion<PhysicalAddress> {
459.     /// Attempts to create a virtual memory region from a physical memory region.
460.     pub fn from_virtual_memory_region(region: MemoryRegion<VirtualAddress>) -> Result<Self, Error> {
461.         let name: String = region.name();
462.         let start: PageAligned<PhysicalAddress> =
463.             PageAligned::from_address(PhysicalAddress::from_virtual_address(region.start())?)?;
464.         let size: usize = region.size();
465.         let typ: MemoryRegionType = region.typ();
466.         let perm: AccessPermission = region.perm();
467.         TruncatedMemoryRegion::new(&name, start, size, typ, perm)
468.     }
469. }
470. 
