 // Invariants
 //==================================================================================================

 impl<T: Address + View<V = int>> MemoryRegion<T> {
     /// A general memory region carries only the non-empty geometry guarantee.
     pub open spec fn inv(&self) -> bool {
         self@.wf()
     }
 }

